rollback.sql:
DO $report_scope_rollback$
BEGIN
    LOCK TABLE clinlims.patient_report_release IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM clinlims.patient_report_release WHERE report_document_id IS NOT NULL) THEN
        RAISE EXCEPTION 'Document releases exist; retain data and use a forward migration';
    END IF;
    DROP INDEX clinlims.uq_patient_report_release_document_draft;
    DROP INDEX clinlims.uq_patient_report_release_document_issued;
    DROP INDEX clinlims.uq_patient_report_release_legacy_version;
    DROP INDEX clinlims.uq_patient_report_release_legacy_number;
    DROP INDEX clinlims.uq_patient_report_release_legacy_draft;
    ALTER TABLE clinlims.patient_report_release DROP CONSTRAINT uq_patient_report_release_document_version;
    ALTER TABLE clinlims.patient_report_release DROP CONSTRAINT fk_patient_report_release_document;
    ALTER TABLE clinlims.patient_report_release DROP COLUMN report_document_id;
    ALTER TABLE clinlims.patient_report_release ADD CONSTRAINT uq_patient_report_release_patient_version UNIQUE (patient_id,report_version);
    ALTER TABLE clinlims.patient_report_release ADD CONSTRAINT uq_patient_report_release_number UNIQUE (report_number);
    CREATE UNIQUE INDEX uq_patient_report_release_active_draft ON clinlims.patient_report_release (patient_id) WHERE status = 'DRAFT';
END;
$report_scope_rollback$;
